static void isert_connected_handler ( struct rdma_cm_id * cma_id ) { struct isert_conn * isert_conn = cma_id -> qp -> qp_context ; struct isert_np * isert_np = cma_id -> context ; isert_info ( "conn %p\n" , isert_conn ) ; mutex_lock ( & isert_conn -> mutex ) ; isert_conn -> state = ISER_CONN_UP ; kref_get ( & isert_conn -> kref ) ; mutex_unlock ( & isert_conn -> mutex ) ; mutex_lock ( & isert_np -> mutex ) ; list_move_tail ( & isert_conn -> node , & isert_np -> pending ) ; mutex_unlock ( & isert_np -> mutex ) ; isert_info ( "np %p: Allow accept_np to continue\n" , isert_np ) ; } 